<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POST </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">resource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 创建指定资源</span></span>
